    sh = lambda rev, p: subprocess.run(["git", "-C", REPO, "show", rev + ":" + p], capture_output=True, text=True, check=True).stdout
    src, incident = sh("071fc53", "scripts/handback.py"), sh("c4aaebb", "__instrumenta__/w06c3_run_all.py")
