                                         "final": False}
                    for f in ("input_tokens", "output_tokens", "cache_read_input_tokens", "cache_creation_input_tokens"):
                        d["usage"][f] = max(int(d["usage"].get(f) or 0), int(use.get(f) or 0))
                    if isinstance(use.get("cache_creation"), dict):
                        d["usage"]["cache_creation"] = use["cache_creation"]
                    d["final"] = d["final"] or bool(m.get("stop_reason"))
    except OSError as err:
        warnings.append("could not read %s: %s" % (path, err.strerror or err))
    return msgs, cost_state, first_ts, agent_setting


def load(mains, dedup=True):
    """Read the sessions, oldest first, and count each message once (the oldest session that holds it keeps it).

    Returns (sessions, stats, warnings). sessions: list of dicts {sid, path, start, cost_state, rows}; rows
    maps (label, kind, model) to Counter of messages, tokens and usd, runs (set), and lower-bound messages."""
    warnings = []
    loaded = []
    for path in mains:
        msgs, cs, ts, setting = read_file(path, warnings)
        loaded.append((ts or "9", path, msgs, cs, setting))
    loaded.sort()
    seen = {}
    stats = collections.Counter()
    sessions = []
    for ts, path, msgs, cs, setting in loaded:
        sid = os.path.basename(path)[:-6]
        srcs = [(setting + " (main thread)" if setting else "main thread", "main", path, msgs)]
        for af in agent_files(path):
            am, _, _, _ = read_file(af, warnings)
            meta = meta_of(af)
            label = meta.get("name") or meta.get("agentType") or ("subagent " + os.path.basename(af)[6:12])
            srcs.append((label, "sub", af, am))
        rows = {}
        for label, kind, file, m in srcs:
            for key, d in m.items():
                stats["records"] += 1
                if dedup:
                    if key in seen:
                        stats["dropped_duplicates"] += 1
                        continue
                    seen[key] = sid
                row = rows.setdefault((label, kind, d["model"]), collections.Counter())
                row["msgs"] += 1
                for f, k in (("input_tokens", "in"), ("output_tokens", "out"), ("cache_read_input_tokens", "cr"),
                             ("cache_creation_input_tokens", "cw")):
