                         "agent_files": len(srcs) - 1})
    return sessions, stats, warnings


# ---------------------------------------------------------------- the human report

def short_model(m):
    return re.sub(r"^claude-", "", m)


def report(root, find="scan", also=(), index=None, dedup=True):
    if find == "v6":
        mains = find_v6(root)
    elif find == "index":
        mains = find_index(index or os.path.join(root, "__expensa__", "runs.jsonl"))
    elif find == "ids":
        mains = find_ids(also)
    else:
        mains = find_scan(root, also)
    sessions, stats, warnings = load(mains, dedup)
    out = ["## Spend (USD, from Claude Code's transcripts; list price of %s)" % "2026-10-19"]
    if not sessions:
        out.append("no transcripts found for %s (looked for sessions whose cwd is the lab or one of its worktrees, under %s)"
                   % (os.path.abspath(root), os.path.join(config_dir(), "projects")))
        return "\n".join(out), {}
    exact = est = 0.0
    lower = False
    per_session = []
    for s in sessions:
        e = sum(r["usd"] for r in s["rows"].values())
        cs = s["cost_state"]
        lb = sum(r["lower_bound_msgs"] for r in s["rows"].values())
        if cs and cs.get("totalCostUSD") is not None:
            per_session.append((s, "exact", cs["totalCostUSD"], e, lb))
            exact += cs["totalCostUSD"]
        else:
            per_session.append((s, "estimate", e, e, lb))
            est += e
            lower = lower or lb > 0
    total = exact + est
    out.append("TOTAL  USD %.2f   (%.2f exact from cost-state of ended sessions, %.2f estimated for the others)" % (total, exact, est))
    if est and lower:
        out.append("The estimate is a LOWER BOUND: a subagent's output tokens are stored at their start-of-stream value "
                   "(about 20-30%% of a Sonnet worker's true cost in the two ended sessions we could compare).")
    out.append("")
    head = ("session", "started", "agents", "USD", "basis")
    tab = [head]
    for s, basis, usd, e, lb in per_session:
        tab.append((s["sid"][:8], (s["start"] or "")[:16].replace("T", " "), str(s["agent_files"]), "%.2f" % usd,
                    basis if basis == "exact" else "estimate" + (" (lower bound)" if lb else "")))
    out += table(tab)
    out.append("")
    # by agent (all sessions): name, model, msgs, USD
    byagent = collections.OrderedDict()
    for s, *_ in per_session:
        for (label, kind, model), r in s["rows"].items():
            a = byagent.setdefault((label, model), collections.Counter())
            a["msgs"] += r["msgs"]
            a["usd"] += r["usd"]
            a["out"] += r["out"]
            a["lb"] += r["lower_bound_msgs"]
    rows = sorted(byagent.items(), key=lambda kv: -kv[1]["usd"])
    tab = [("agent", "model", "msgs", "est. USD", "output tokens")]
    for (label, model), a in rows[:15]:
        tab.append((label, short_model(model), str(a["msgs"]), "%.2f" % a["usd"], "{:,}".format(a["out"]) + ("+" if a["lb"] else "")))
    if len(rows) > 15:
        rest = rows[15:]
        tab.append(("(%d more)" % len(rest), "", str(sum(a["msgs"] for _, a in rest)), "%.2f" % sum(a["usd"] for _, a in rest), ""))
    out += table(tab)
    out.append("`+` = output tokens are a lower bound. Per-agent USD is an estimate even in a session with an exact total.")
    if stats["dropped_duplicates"]:
        out.append("%d of %d records were copies of a message already counted (forked sessions, copied agent files) and are not counted again."
                   % (stats["dropped_duplicates"], stats["records"]))
    out += ["! " + w for w in warnings]
    summary = {"total": total, "exact": exact, "estimate": est, "sessions": len(sessions), "dropped": stats["dropped_duplicates"],
               "records": stats["records"], "per_session": [(s["sid"], b, u, e) for s, b, u, e, lb in per_session]}
    return "\n".join(out), summary


def table(rows):
    widths = [max(len(r[i]) for r in rows) for i in range(len(rows[0]))]
    lines = []
    for n, r in enumerate(rows):
        lines.append("  ".join(c.ljust(widths[i]) if i < 2 or not c[:1].isdigit() else c.rjust(widths[i]) for i, c in enumerate(r)).rstrip())
        if n == 0:
            lines.append("  ".join("-" * w for w in widths))
    return lines


def main(argv):
    root = os.environ.get("CLAUDE_PROJECT_DIR") or os.getcwd()
    find, also, index, dedup = "scan", [], None, True
    i = 0
    while i < len(argv):
        a = argv[i]
        if a == "--root":
            root = argv[i + 1]; i += 1
        elif a == "--find":
            find = argv[i + 1]; i += 1
        elif a == "--also":
            also.append(argv[i + 1]); i += 1
        elif a == "--index":
            index = argv[i + 1]; i += 1
        elif a == "--config-dir":
            os.environ["CLAUDE_CONFIG_DIR"] = argv[i + 1]; i += 1
        elif a == "--no-dedup":
            dedup = False
        else:
            print("lab_spend.py: unknown argument %s" % a, file=sys.stderr)
            return 2
        i += 1
    text, _ = report(root, find, also, index, dedup)
    print(text)
    return 0


if __name__ == "__main__":
    sys.exit(main(sys.argv[1:]))

